"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '
# Check 4: manifest-driven copy verification
# The build script uses inventory() to scan OUT directory and generate MANIFEST.json
# Verify that the actual SHA256 of each file matches MANIFEST.json

$buildDir = "E:'"\\VPS\\terminalization_v2_build\"
"'$manifest = Get-Content "$buildDir'"\\MANIFEST.json\" | ConvertFrom-Json

Write-Host \"=== SHA256 live computation vs MANIFEST ===\"
"'$allPass = $true
foreach ($entry in $manifest.files) {
    $filePath = Join-Path $buildDir $entry.relative_path
    if (Test-Path $filePath) {
        $actualHash = (Get-FileHash $filePath -Algorithm SHA256).Hash.ToLower()
        $expectedHash = $entry.sha256.ToLower()
        $match = $actualHash -eq $expectedHash
        if (-not $match) { $allPass = $false }
        $status = if ($match) { "MATCH" } else { "MISMATCH" }
        Write-Host "  [$status] $($entry.relative_path)"
        if (-not $match) {
            Write-Host "    Expected: $expectedHash"
            Write-Host "    Actual:   $actualHash"
        }
    } else {
        Write-Host "  [MISSING] $($entry.relative_path)"
        $allPass = $false
    }
}
Write-Host ""
if ($allPass) { Write-Host "=== ALL MANIFEST HASHES MATCH (PASS) ===" } else { Write-Host "=== HASH MISMATCH DETECTED (FAIL) ===" }
'

