"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '
# Check 5: post-install rehash - verify SHA256SUMS matches MANIFEST.json and live files
$buildDir = "E:'"\\VPS\\terminalization_v2_build\"
"'$manifest = Get-Content "$buildDir'"\\MANIFEST.json\" | ConvertFrom-Json

# Parse SHA256SUMS file
Write-Host \"=== Cross-verifying SHA256SUMS vs MANIFEST.json ===\"
"'$sha256sumsContent = Get-Content "$buildDir'"\\SHA256SUMS\"
"'$sha256sumsDict = @{}
foreach ($line in $sha256sumsContent) {
    if ($line.Trim() -ne "") {
        $parts = $line -split "'"\\s+\", 2
        if ("'$parts.Length -eq 2) {
            $sha256sumsDict[$parts[1].Trim()] = $parts[0].Trim()
        }
    }
}

Write-Host "Files in SHA256SUMS: $($sha256sumsDict.Count)"
Write-Host "Files in MANIFEST: $($manifest.files.Count)"

$allPass = $true
foreach ($entry in $manifest.files) {
    $manifestHash = $entry.sha256.ToLower()
    $sumsHash = if ($sha256sumsDict.ContainsKey($entry.relative_path)) { $sha256sumsDict[$entry.relative_path].ToLower() } else { "NOT_IN_SUMS" }
    $match = $manifestHash -eq $sumsHash
    if (-not $match) { $allPass = $false }
    $status = if ($match) { "MATCH" } else { "MISMATCH" }
    Write-Host "  [$status] $($entry.relative_path)"
    if (-not $match) {
        Write-Host "    MANIFEST: $manifestHash"
        Write-Host "    SHA256SUMS: $sumsHash"
    }
}

Write-Host ""
Write-Host "=== SHA256SUMS entries not in MANIFEST ==="
foreach ($key in $sha256sumsDict.Keys) {
    $inManifest = ($manifest.files | Where-Object { $_.relative_path -eq $key }) -ne $null
    if (-not $inManifest) {
        Write-Host "  EXTRA: $key"
    }
}

Write-Host ""
if ($allPass) { Write-Host "=== SHA256SUMS CROSS-CHECK PASS ===" } else { Write-Host "=== SHA256SUMS CROSS-CHECK FAIL ===" }
'

