"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '
# Final comprehensive verification: live bytes -> SHA256 -> vs SHA256SUMS vs MANIFEST
# This simulates a post-install rehash
$buildDir = "E:'"\\VPS\\terminalization_v2_build\"
"'$sha256sumsContent = Get-Content "$buildDir'"\\SHA256SUMS\"
"'$sha256sumsDict = @{}
foreach ($line in $sha256sumsContent) {
    if ($line.Trim() -ne "") {
        $parts = $line -split "'"\\s+\", 2
        if ("'$parts.Length -eq 2) {
            $sha256sumsDict[$parts[1].Trim()] = $parts[0].Trim()
        }
    }
}

Write-Host "=== Post-install rehash: live bytes -> SHA256 vs SHA256SUMS ==="
$allPass = $true
foreach ($entry in $sha256sumsDict.GetEnumerator()) {
    $filePath = Join-Path $buildDir $entry.Key
    if (Test-Path $filePath) {
        $liveHash = (Get-FileHash $filePath -Algorithm SHA256).Hash.ToLower()
        $expectedHash = $entry.Value.ToLower()
        $match = $liveHash -eq $expectedHash
        if (-not $match) { $allPass = $false }
        $status = if ($match) { "OK" } else { "FAIL" }
        Write-Host "  [$status] $($entry.Key)"
    } else {
        Write-Host "  [MISSING] $($entry.Key)"
        $allPass = $false
    }
}
Write-Host ""
if ($allPass) { Write-Host "=== POST-INSTALL REHASH: PASS ===" } else { Write-Host "=== POST-INSTALL REHASH: FAIL ===" }

# Also check size_bytes from manifest
Write-Host ""
Write-Host "=== Size_bytes verification ==="
$manifest = Get-Content "$buildDir'"\\MANIFEST.json\" | ConvertFrom-Json
"'$sizeAllPass = $true
foreach ($entry in $manifest.files) {
    $filePath = Join-Path $buildDir $entry.relative_path
    $actualSize = (Get-Item $filePath).Length
    $match = $actualSize -eq $entry.size_bytes
    if (-not $match) { $sizeAllPass = $false }
    $status = if ($match) { "OK" } else { "MISMATCH" }
    Write-Host "  [$status] $($entry.relative_path) expected=$($entry.size_bytes) actual=$actualSize"
}
if ($sizeAllPass) { Write-Host "=== SIZE CHECK: PASS ===" } else { Write-Host "=== SIZE CHECK: FAIL ===" }
'

